@IsTest private class OwnedAssignmentIdentityProbe {
 private static Id reader(){return [SELECT Id FROM PermissionSet WHERE Name='OwnedReader'].Id;}
 private static void verify(){System.runAs(new User(Id=UserInfo.getUserId())){Assert.isTrue(FeatureManagement.checkPermission('OwnedView'));Assert.isFalse(FeatureManagement.checkPermission('OwnedEdit'));Assert.isFalse(FeatureManagement.checkPermission('UndeclaredPermission'));}}
 @IsTest static void directControl(){insert new PermissionSetAssignment(AssigneeId=UserInfo.getUserId(),PermissionSetId=reader());verify();}
 @IsTest static void expandedSetReference(){String parent=reader().toString();Assert.areEqual(18,parent.length());insert new PermissionSetAssignment(AssigneeId=UserInfo.getUserId(),PermissionSetId=parent);verify();}
 @IsTest static void expandedAssigneeReference(){String userId=UserInfo.getUserId().toString();Assert.areEqual(18,userId.length());insert new PermissionSetAssignment(AssigneeId=userId,PermissionSetId=reader());verify();}
 private static Object expand(Object value){return value instanceof String?((String)value).replace('[index]','0'):value;}
 @IsTest static void expandedTokenMapReferences(){Map<Schema.SObjectField,Object> values=new Map<Schema.SObjectField,Object>{PermissionSetAssignment.AssigneeId=>UserInfo.getUserId(),PermissionSetAssignment.PermissionSetId=>reader()};SObject row=PermissionSetAssignment.SObjectType.newSObject();for(Schema.SObjectField field:values.keySet())row.put(field,expand(values.get(field)));insert row;verify();}
 @IsTest static void unassignedControl(){Id parent=reader();Id userId=UserInfo.getUserId();Assert.areEqual(0,[SELECT COUNT() FROM PermissionSetAssignment WHERE AssigneeId=:userId AND PermissionSetId=:parent]);Assert.isFalse(FeatureManagement.checkPermission('OwnedView'));}
 @IsTest static void disabledControl(){insert new PermissionSetAssignment(AssigneeId=UserInfo.getUserId(),PermissionSetId=reader());System.runAs(new User(Id=UserInfo.getUserId())){Assert.isFalse(FeatureManagement.checkPermission('OwnedEdit'));Assert.isFalse(FeatureManagement.checkPermission('UndeclaredPermission'));}}
}
